<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PracticeControlController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->hasRole('practice_head')||$r->user()->canDo('practice.manage'),403);}
public function loads(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$rows=DB::table('practice_supervision_loads as l')->join('teachers as t','t.id','=','l.teacher_id')->join('practice_campaigns as c','c.id','=','l.practice_campaign_id')->where('l.academic_period_id',$p->id)->select('l.*','t.last_name','t.first_name','c.title')->orderBy('t.last_name')->get();$teachers=DB::table('teachers')->orderBy('last_name')->get();$campaigns=DB::table('practice_campaigns')->where('academic_period_id',$p->id)->orderBy('starts_on')->get();return view('practice-office.loads',compact('rows','teachers','campaigns'));}
public function loadStore(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['teacher_id'=>'required|exists:teachers,id','practice_campaign_id'=>'required|exists:practice_campaigns,id','planned_hours'=>'required|numeric|min:0','actual_hours'=>'nullable|numeric|min:0','note'=>'nullable|string|max:3000']);DB::table('practice_supervision_loads')->updateOrInsert(['teacher_id'=>$d['teacher_id'],'practice_campaign_id'=>$d['practice_campaign_id']],$d+['academic_period_id'=>$p->id,'updated_at'=>now(),'created_at'=>now()]);return back();}
public function attendance(Request $r,$placement){$this->manage($r);$p=DB::table('practice_placements')->find($placement);abort_if(!$p,404);$student=DB::table('students')->find($p->student_id);$rows=DB::table('practice_attendance')->where('practice_placement_id',$placement)->orderByDesc('work_date')->get();return view('practice-office.attendance',compact('p','student','rows'));}
public function attendanceStore(Request $r,$placement){$this->manage($r);$d=$r->validate(['work_date'=>'required|date','status'=>'required|in:present,absent,excused,sick','hours'=>'required|numeric|min:0|max:24','note'=>'nullable|string|max:2000']);DB::table('practice_attendance')->updateOrInsert(['practice_placement_id'=>$placement,'work_date'=>$d['work_date']],$d+['marked_by'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);return back();}
public function photo(Request $r,$placement){$this->manage($r);$d=$r->validate(['photo'=>'required|image|max:10240','work_date'=>'nullable|date','caption'=>'nullable|string|max:1000']);$f=$r->file('photo');$path=$f->store('practice/photos/'.$placement,'local');DB::table('practice_photo_reports')->insert(['practice_placement_id'=>$placement,'work_date'=>$d['work_date']??null,'path'=>$path,'original_name'=>$f->getClientOriginalName(),'mime'=>$f->getMimeType(),'size'=>$f->getSize(),'caption'=>$d['caption']??null,'uploaded_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function safety(Request $r,$placement){$this->manage($r);$d=$r->validate(['type'=>'required|in:introductory,workplace,fire,electrical,ppe,other','checked_on'=>'required|date','instructor'=>'nullable|string|max:255','status'=>'required|in:confirmed,missing,expired','note'=>'nullable|string|max:3000']);DB::table('practice_safety_checks')->insert($d+['practice_placement_id'=>$placement,'checked_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function agreementsControl(Request $r){$this->manage($r);$rows=DB::table('practice_agreements as a')->join('practice_organizations as o','o.id','=','a.practice_organization_id')->select('a.*','o.name organization_name')->orderByRaw('valid_to IS NULL')->orderBy('valid_to')->get();return view('practice-office.agreements-control',compact('rows'));}
public function analytics(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$orgs=DB::table('practice_placements as pp')->leftJoin('practice_employment_results as e','e.practice_placement_id','=','pp.id')->where('pp.academic_period_id',$p->id)->select('pp.organization_name',DB::raw('COUNT(*) students'),DB::raw("SUM(CASE WHEN e.status='employed' THEN 1 ELSE 0 END) employed"),DB::raw("SUM(CASE WHEN pp.attestation_grade IS NOT NULL AND pp.attestation_grade<>'' THEN 1 ELSE 0 END) attested"))->groupBy('pp.organization_name')->orderByDesc('students')->get();$types=DB::table('practice_placements')->where('academic_period_id',$p->id)->select('practice_type',DB::raw('COUNT(*) total'))->groupBy('practice_type')->get();return view('practice-office.analytics',compact('orgs','types'));}
}